window.products.push({"id":312946,"name":"Large Wood Airplane Propeller Wine Rack","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/91GcbbgfSDL._AC_SL1500_.jpg","description":"A new addition to our popular propeller furniture line, this handsome wine rack features a 38-inch WWI replica mahogany and brass propeller on either side. Functional design allows room for fifteen bottles of your favorite vintage--stored at a slight angle to keep the cork from drying out. Storage drawer below for corkscrews, napkins, etc., as well as slots for hanging six wine glasses (glass stems cannot be over 2.5 inches in diameter). Size: 50 High, 17 Wide, 12 Deep Item No. 633","images":["https://m.media-amazon.com/images/I/91GcbbgfSDL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"HNE","source_asin":"B00E9FODLE","category_path":"Home & Kitchen"},"sku":"BM-312946","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00E9FODLE","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00E9FODLE","price_pending":true,"merchant_ready":false});
